/**
 * Pass a stream and other params to this._composeSecure to start crypto
 * encapsulation.
 *
 * @param {?string} headers - Top level headers to protect, if any.
 */
_startCryptoEncapsulation(headers) {
  const recipients = [
    this._compFields.to,
    this._compFields.cc,
    this._compFields.bcc,
    this._compFields.newsgroups,
  ]
    .filter(Boolean)
    .join(",");

  this._composeSecure.beginCryptoEncapsulation(
    this._fstream,
    recipients,
    this._compFields,
    headers,
    this._userIdentity,
    this._sendReport,
    this._deliverMode == Ci.nsIMsgSend.nsMsgSaveAsDraft
  );
  this._cryptoEncapsulationStarted = true;
}

